    "description": {
      "en": ": What the scheme is: MGNREGS is a social security measure anchored in the Mahatma Gandhi National Rural Employment Guarantee Act (2005). It provides a legal, rights-based guarantee of wage employment to adult members of rural households."
    },
    "whyStarted": {
      "en": "The scheme was enacted to enhance economic livelihood security in rural India, curb distress seasonal migration to urban centers, build durable rural infrastructure (water conservation, check dams, roads), and empower marginalized rural communities."
    },
    "whoCanBenefit": {
      "en": "Any adult member of a rural household residing within the Gram Panchayat area who is willing to undertake manual unskilled public work."
    },
    "howItWorks": {
      "en": "Households register with their local Gram Panchayat to obtain a Job Card. Cardholders submit written demands for employment. The Gram Panchayat is legally bound to provide work within 15 days of receiving the request within 5 km of the worker's home."
    },
    "governmentSupport": {
      "en": "Guaranteed 100 days of unskilled wage employment per household per financial year (up to 150 days in notified drought or natural disaster areas). Wages are transferred directly into bank/post office accounts via Direct Benefit Transfer (DBT). Worksites provide essential facilities including drinking water, shade, first-aid, and crèches."
    },
    "keyBenefits": {
      "en": "Guaranteed wage employment, statutory unemployment allowance if work is not allotted within 15 days, equal wages for male and female workers, and creation of durable community water and agricultural assets."
    },
    "benefits": [
      {
        "en": "Guaranteed wage employment, statutory unemployment allowance if work is not allotted within 15 days, equal wages for male and female workers, and creation of durable community water and agricultural assets."
      }
    ],
    "importantConditions": [
      {
        "en": "Work must be requested in writing. Daily attendance is digitally captured twice a day using geotagged photos on the National Mobile Monitoring System (NMMS). Contractors and labor-displacing heavy machinery are strictly prohibited."
      }
    ],
    "eligibilityCriteria": {
      "en": ": Resident of a rural household; adult member (18 years or older); willing to undertake manual unskilled labor; registered with the local Gram Panchayat and holding a valid MGNREGA Job Card."
    },
    "ageLimit": {
      "en": "Minimum 18 Years (No upper age ceiling provided the person is physically capable of manual work)."
    },
    "incomeLimit": {
      "en": "Not Applicable. Scheme Name: Mahatma Gandhi National Rural Employment Guarantee Scheme (MGNREGS) Category: Employment & Skill Development Subcategory: Rural Guaranteed Wage Employment & Livelihood Security Government Level: Central Government (Implemented via States) Implementing Ministry: Ministry of Rural Development (MoRD) State: All States & UTs (Rural Areas) Status: ACTIVE"
    },
    "requiredDocuments": [
      {
        "en": ": Aadhaar Card, Proof of Residence in Gram Panchayat (Ration Card/Voter ID), Passport-size Photographs of all adult household applicants, Bank or Post Office Account details."
      }
    ],
    "applicationProcess": [
      {
        "en": ": Submit a written or oral application for Job Card registration at the local Gram Panchayat office. Gram Panchayat verifies household details and issues a free MGNREGA Job Card containing a unique family registration ID. Submit a written application for work to the Gram Panchayat, specifying the desired period and duration of employment. Receive a dated receipt and formal work allotment letter indicating the worksite within 15 days. Report to the assigned worksite; daily attendance is logged digitally via the NMMS application."
      }
    ],
