    "description": {
      "en": "The House Building Advance (HBA) Scheme is a long-standing financial welfare measure provided by the Central Government to assist its employees in acquiring residential housing. The primary goal of starting this scheme is to help government servants build or buy their own homes at concessional interest rates, reducing their dependence on expensive commercial home loans."
    },
    "whyStarted": {
      "en": "To enable civil servants to construct, purchase, or expand self-owned housing property through affordable interest rates and organized salary recovery mechanisms. Who can get the benefit &"
    },
