    "description": {
      "en": "What the scheme is: The Kisan Credit Card (KCC) scheme is an essential agricultural credit mechanism designed to provide farmers with timely, flexible, and simplified credit support from formal banks through a single revolving credit card account."
    },
    "whyStarted": {
      "en": "Introduced in 1998 (and expanded in 2019 to include Animal Husbandry, Dairying, and Fisheries), KCC was created to eliminate reliance on informal moneylenders and ensure working capital for crop cultivation, post-harvest expenses, and farm asset maintenance."
    },
    "whoCanBenefit": {
      "en": "All owner cultivators, tenant farmers, sharecroppers, oral lessees, and Self Help Groups (SHGs) or Joint Liability Groups (JLGs) of farmers, including animal husbandry and fisheries practitioners. How the scheme works & Subsidized Interest Structure: Farmers receive a revolving credit limit valid for 5 years. Short-term crop loans up to ₹3 Lakhs carry a base interest rate of 7% per annum. Under the Central Government Interest Subvention Scheme: Government provides 2% Interest Subvention to lending banks. Government provides an additional 3% Prompt Repayment Incentive (PRI) directly to farmers who pay on time. Effective Interest Rate: Drops to just 4% per annum for prompt repaying farmers. What help government provides: Massive interest subvention, collateral-free loan limit up to ₹1.60 Lakhs (extendable to ₹2 Lakhs for tie-ups), personal accident insurance coverage, and RuPay KCC debit cards for easy ATM cash withdrawals. How it helps people & Important rules: Substantially reduces agricultural input costs and protects farmers from distress sales. Credit limits are based on crop area, cropping pattern, and scale of finance."
    },
