    "description": ": What the scheme is: MGNREGS is a social security measure anchored in the Mahatma Gandhi National Rural Employment Guarantee Act (2005). It provides a legal, rights-based guarantee of wage employment to adult members of rural households.",
    "whyStarted": "The scheme was enacted to enhance economic livelihood security in rural India, curb distress seasonal migration to urban centers, build durable rural infrastructure (water conservation, check dams, roads), and empower marginalized rural communities.",
