    "incomeLimit": "Not Applicable. Scheme Name: Mahatma Gandhi National Rural Employment Guarantee Scheme (MGNREGS) Category: Employment & Skill Development Subcategory: Rural Guaranteed Wage Employment & Livelihood Security Government Level: Central Government (Implemented via States) Implementing Ministry: Ministry of Rural Development (MoRD) State: All States & UTs (Rural Areas) Status: ACTIVE",
