    "status": "ACTIVE",
    "description": ": What the scheme is: PMEGP is a credit-linked capital subsidy scheme designed to assist aspiring micro-entrepreneurs in setting up self-employment ventures in the manufacturing and service sectors. 1. 2. 3. 4. 5. Scheme Name: Prime Minister's Employment Generation Programme (PMEGP) Category: Employment & Skill Development Subcategory: Self-Employment & Micro- Enterprise Credit Subsidies Government Level: Central Government Implementing Ministry: Ministry of Micro, Small and Medium Enterprises (MSME) State: All States & UTs (Pan-India) Status: ACTIVE",
    "whyStarted": "Introduced to generate continuous sustainable self-employment opportunities in non-farm sectors, curb rural-to-urban migration, utilize traditional skills, and expand the micro-enterprise ecosystem nationwide.",
    "whoCanBenefit": "Individual entrepreneurs, Self Help Groups (SHGs), Institutions registered under the Societies Registration Act (1860), Production Co-operative Societies, and Charitable Trusts.",
    "howItWorks": "The Khadi and Village Industries Commission (KVIC) serves as the national nodal agency. Implementation is handled by KVIC State Directorates, State Khadi & Village Industries Boards (KVIBs), District Industries Centres (DICs), and Coir Board. Applicants apply online, secure bank loans, and obtain back-ended government margin money subsidies.",
    "governmentSupport": "Capital Margin Money subsidy ranging from 15% to 35% of project cost. Maximum project cost allowed is ₹50 Lakh for manufacturing units and ₹20 Lakh for service units. Second-stage loans up to ₹1 Crore for expansion of existing successful PMEGP units are available with 15% subsidy.",
    "keyBenefits": "Direct capital investment subsidy, credit guarantee coverage under CGTMSE (no collateral for loans up to ₹10 Lakh), mandatory Entrepreneurship Development Programme (EDP) training, and long-term business mentoring.",
    "benefits": [
      "Direct capital investment subsidy, credit guarantee coverage under CGTMSE (no collateral for loans up to ₹10 Lakh), mandatory Entrepreneurship Development Programme (EDP) training, and long-term business mentoring."
    ],
    "importantConditions": [
      "Beneficiary contribution is 10% of project cost for General Category and 5% for Special Categories (SC/ST/OBC/Minorities/Women/Ex-Servicemen/PWD/NER/Hilly areas). Land cost cannot be included in project funding. Applies strictly to new micro-enterprises."
    ],
    "eligibilityCriteria": ": Any individual above 18 years of age; minimum 8th standard pass for manufacturing projects exceeding ₹10 Lakh and service projects exceeding ₹5 Lakh; applies only to new micro-enterprise units; restricted to one member per family.",
    "ageLimit": "Minimum 18 Years (No upper age limit).",
    "incomeLimit": "Not Applicable.",
    "requiredDocuments": [
      ": Aadhaar Card, PAN Card, Detailed Project Report (DPR), Educational Qualification Certificate (8th pass marksheet minimum for higher project costs), Caste/Category Certificate (if claiming special subsidy), Rural Area Certificate from Gram Panchayat (for rural subsidy benefits), Bank Account Details."
    ],
    "applicationProcess": [
      ": Prepare a Detailed Project Report (DPR) or choose a sample project profile from the KVIC portal. Access the official PMEGP e-Portal (www.kviconline.gov.in/pmegpeportal/) and click \"Application for Individual\". Fill out online form details including personal credentials, chosen agency (KVIC/KVIB/DIC), and preferred financing bank branch. Upload scanned documents (Aadhaar, photo, project report, qualification proof). After agency document review, bank sanction, and mandatory online EDP training completion, loan and margin money subsidy are disbursed."
    ],
    "officialApplicationUrl": "https://www.kviconline.gov.in/pmegpeportal/",
