    "description": "The National Pension System (NPS) is a defined-contribution pension framework designed to build a dedicated retirement corpus for government employees. Introduced by the Government of India to transition away from traditional defined-benefit pension liabilities, NPS was made mandatory for all Central Government employees (except Armed Forces) who joined service on or after January 1, 2004. Subsequently, almost all State Governments adopted NPS for their civil servants.",
