    "keyBenefits": "OPD & Free Medicines: Comprehensive outpatient consultation and free medicine dispensing at CGHS Wellness Centres. Cashless Hospitalization: Cashless inpatient treatment at private empaneled hospitals for pensioners and emergency cases. Holistic Care (AYUSH): Equal access to accredited Ayurveda, Homeopathy, Unani, Siddha, and Naturopathy treatment centres. Diagnostic Coverage: Diagnostic tests and investigations at pre-approved CGHS rates across empaneled laboratories. Lifetime Pensioner Coverage: One-time payment option for lifetime CGHS card validity post-retirement.",
