    "description": "SPARSH (System for Pension Administration - Raksha) is a web-based integrated pension sanction and disbursement portal implemented by the Ministry of Defence. SPARSH manages the end-to-end pension lifecycle for Indian Armed Forces personnel—including Indian Army, Indian Navy, Indian Air Force, and Defence Civilian employees—from initial pension sanction calculation to direct monthly pension credit into bank accounts.",
    "whyStarted": "Historically, defence pension processing relied on external agency banks and multiple record offices, resulting in delayed pension initiation, high bank processing fees, delayed grievance resolution, and communication gaps. SPARSH was created to establish a direct, transparent, and automated digital portal. Who can get the benefit &",
    "whoCanBenefit": "Eligible Indian citizens meeting criteria across All States & UTs (All-India Coverage) STATUS.",
    "howItWorks": "Retired and serving personnel of the Army, Navy, Air Force, Defence Civilians, and their family pensioners are covered. Departmental record offices upload service parameters directly to SPARSH. The system calculates pension, generates digital PPOs, and credits monthly pension straight into beneficiaries' bank accounts via Direct Benefit Transfer (DBT). What help the government provides &",
    "governmentSupport": "Direct Pension Credit: Timely pension payment directly from Defence Treasury to bank account without external bank delay. Transparent Online Portal: 24/7 access to monthly pension slips, Form 16 tax documents, and e-PPO copies. Seamless Identification: Direct linkage with Jeevan Pramaan Face RD and digital life certificate system. Dedicated Grievance Redressal: Dedicated online ticketing and resolution portal specifically for defence pensioners. Zero Intermediary Fees: Eliminates bank agency commission, saving public funds while improving speed.",
    "keyBenefits": "Direct Pension Credit: Timely pension payment directly from Defence Treasury to bank account without external bank delay. Transparent Online Portal: 24/7 access to monthly pension slips, Form 16 tax documents, and e-PPO copies. Seamless Identification: Direct linkage with Jeevan Pramaan Face RD and digital life certificate system. Dedicated Grievance Redressal: Dedicated online ticketing and resolution portal specifically for defence pensioners. Zero Intermediary Fees: Eliminates bank agency commission, saving public funds while improving speed.",
