    "whyStarted": "Historically, millions of informal micro-entrepreneurs, shopkeepers, fruit/vegetable vendors, and small artisans were excluded from formal banking channels. They were forced to rely on local moneylenders charging extortionate interest rates. PMMY was launched to \"fund the unfunded\" and integrate micro-units into the formal financial ecosystem.",
