    "whyStarted": "Traditional artisans (Vishwakarmas) preserve cultural heritage but often face low earnings, lack modern tools, and struggle to access formal credit or organized markets. The scheme was introduced to uplift artisans, modernize their toolkits, and integrate them into national value chains. 18 Eligible Trades: Carpenter (Suthar), Boat Maker, Armourer, Blacksmith (Lohar), Locksmith, Gold/Silversmith (Sonar), Potter (Kumhaar), Sculptor (Moortikar)/Stone Carver, Cobbler (Charmakar), Mason (Rajmistri), Basket/Mat/Broom Maker, Doll & Toy Maker (Traditional), Barber (Naai), Garland Maker (Malakaar), Washerman (Dhobi), Tailor (Darzi), Fishing Net Maker, and Tool Kit Maker. How the scheme works & Financial Support: Recognition & Skill Training: Formal PM Vishwakarma ID card, followed by 5-7 days basic skill training (with ₹500/day stipend). Toolkit Incentive: ₹15,000 e-voucher provided upon completion of basic skill training to purchase modern tools. Collateral-Free Credit Support: Up to ₹3 Lakhs total credit in two tranches: • Tranche 1: Loan up to ₹1,00,000 (18-month tenure) at concessional 5% interest rate. • Tranche 2: Loan up to ₹2,00,000 (30-month tenure) at 5% interest rate after clearing Tranche 1. • Interest Subvention: Govt provides an 8% interest subvention directly to banks to cap borrower rate at 5%. How it helps people & Important rules: Modernizes traditional trades, provides collateral-free credit, and offers e-commerce/ market linkages. Restricted strictly to ONE member per family. Must not have active loans under PMEGP, Mudra, or PM SVANidhi for similar trade in the past 5 years.",
