    "whyStarted": "First-generation entrepreneurs and small business owners often face loan rejections because they lack real estate or collateral assets to pledge as security. Launched in July 2000, CGTMSE removes this primary obstacle by covering credit default risks on behalf of lenders.",
    "whoCanBenefit": "New and existing Micro and Small Enterprises (MSEs) engaged in manufacturing, services, retail trade, and technology-driven operations. How the scheme works & Guarantee Coverage: Member Lending Institutions (MLIs)—including Commercial Banks, SFBs, RRBs, NBFCs, and SIDBI—issue term loans and working capital to MSEs without demanding collateral. CGTMSE provides credit guarantee coverage ranging from 75% to 85% (and up to 90% for priority groups) of the loan amount up to a maximum credit ceiling of ₹5 Crore per borrower. What help government provides: Assures default cover up to 90%, caps annual guarantee fees to very low levels (starting at 0.37% per annum), and absorbs credit default risk for banks, boosting credit flow into the small enterprise sector. How it helps people & Important rules: Allows ambitious entrepreneurs to expand operations without collateral. Applicable strictly to Micro and Small Enterprises as per MSMED Act definition (Medium enterprises excluded). Enterprise must hold valid MSME Udyam Registration.",
