    "description": "What the scheme is: PM-Vidyalaxmi is a mission-mode Central Government scheme designed to ensure that financial constraints never prevent any deserving youth in India from pursuing quality higher education in premier institutions. It provides collateral-free and guarantor-free education loans along with interest subvention through a unified digital portal.",
    "whyStarted": "Escalating costs of higher education at top-ranked institutions (such as IITs, NITs, IIMs, AIIMS, and Central Universities) pose significant financial barriers for middle and lower-income families. Traditional education loans frequently demand physical collateral or third-party guarantors. PM-Vidyalaxmi was instituted to eliminate these structural barriers in alignment with National Education Policy (NEP) 2020.",
