    "howItWorks": "Students register and apply digitally on the dedicated PM-Vidyalaxmi portal. Partnered commercial banks evaluate applications digitally without asking for property security or guarantors. The Government of India provides a 75% credit guarantee to banks for default coverage on loans up to ₹7.5 Lakhs, ensuring fast loan sanctions.",
